const KEY='tecnofa_v5';
const EMPTY={clients:[],plants:[],interventions:[],appointments:[],maintenance:[],quotes:[],materials:[],stockMoves:[],expenses:[],documents:[],audit:[]};
let db=JSON.parse(localStorage.getItem(KEY)||localStorage.getItem('tecnofa_v4')||localStorage.getItem('tecnofa_v3')||localStorage.getItem('tecnofa_v2')||localStorage.getItem('tecnofa_v1')||'null')||structuredClone(EMPTY);
for(const k of Object.keys(EMPTY))if(!Array.isArray(db[k]))db[k]=[];
const $=s=>document.querySelector(s), now=()=>new Date().toISOString(), today=()=>new Date().toISOString().slice(0,10), uid=p=>p+'_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={home:'Dashboard',agenda:'Agenda',clienti:'Clienti',impianti:'Impianti',interventi:'Interventi',manutenzioni:'Manutenzioni',preventivi:'Preventivi',magazzino:'Magazzino',economia:'Economia',documenti:'Documenti',mappa:'Mappa & percorsi',energia:'Energia',ai:'TECNOFA AI',impostazioni:'Impostazioni'};
const STATES=['bozza','programmato','assegnato','confermato','in viaggio','in corso','sospeso','da completare','in attesa','da preventivare','completato','da validare','chiuso','annullato','archiviato'];
const TYPES=['guasto','manutenzione','installazione','sopralluogo','collaudo','assistenza','altro'];
const OUTCOMES=['risolto','non risolto','attesa ricambio','da preventivare','manutenzione futura','garanzia'];
function save(){localStorage.setItem(KEY,JSON.stringify(db))}
function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2400)}
function modal(h){$('#modal-content').innerHTML=h;$('#modal').classList.remove('hidden')}
function closeModal(){ $('#modal').classList.add('hidden') }
function log(id,action,details,type='system'){db.audit.push({id:uid('mov'),entityId:id,entityType:type,action,details,at:now()});save()}
function cname(id){return db.clients.find(x=>x.id===id)?.name||'—'} function pname(id){return db.plants.find(x=>x.id===id)?.name||'—'}
function options(records,value,label=k=>k.name||k.title||k.id,empty='—'){return `<option value="">${empty}</option>`+records.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(label(x))}</option>`).join('')}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function textarea(label,name,value='',extra=''){return `<div class="field full"><label>${label}</label><textarea name="${name}" ${extra}>${esc(value)}</textarea></div>`}
function select(label,name,opts,value='',extra=''){return `<div class="field"><label>${label}</label><select name="${name}" ${extra}>${opts.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`}
function header(t,b=''){return `<div class="section-head"><h2>${t}</h2>${b}</div>`}
function tabs(items){return `<div class="tabs">${items.map(x=>`<button class="btn" onclick="${x[1]}">${x[0]}</button>`).join('')}</div>`}
function badge(s){return `<span class="badge ${['chiuso','completato','attiva','accettato'].includes(s)?'green':(['annullato','rifiutato'].includes(s)?'danger':'orange')}">${esc(s||'—')}</span>`}
function historyHtml(ids){const set=new Set(Array.isArray(ids)?ids:[ids]);const h=db.audit.filter(x=>set.has(x.entityId)).sort((a,b)=>b.at.localeCompare(a.at));return `<div class="history">${h.map(x=>`<div class="row"><div><b>${esc(x.action)}</b><div class="muted">${esc(x.details)}</div></div><span class="muted">${new Date(x.at).toLocaleString('it-IT')}</span></div>`).join('')||'<div class="empty">Nessun movimento registrato.</div>'}</div>`}
function linkedIds(clientId){return [clientId,...db.plants.filter(x=>x.clientId===clientId).map(x=>x.id),...db.interventions.filter(x=>x.clientId===clientId).map(x=>x.id),...db.maintenance.filter(x=>x.clientId===clientId).map(x=>x.id),...db.quotes.filter(x=>x.clientId===clientId).map(x=>x.id),...db.documents.filter(x=>x.clientId===clientId).map(x=>x.id)]}
function nav(){const r=location.hash.replace('#/','')||'home';({home,agenda,clienti,impianti,interventi,manutenzioni,preventivi,magazzino,economia,documenti,mappa,energia,ai:aiPage,impostazioni}[r]||home)();document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===r));$('#page-title').textContent=titles[r]||'Dashboard';$('#page-eyebrow').textContent='TECNOFA • '+(titles[r]||'Dashboard');$('#sidebar').classList.remove('open')}
window.addEventListener('hashchange',nav);$('#modal-close').onclick=closeModal;$('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};$('#menu-btn').onclick=()=>$('#sidebar').classList.toggle('open');$('#quick-add').onclick=quick;
function quick(){modal(`<h2>Nuova attività</h2><div class="grid grid-2"><button class="btn green" onclick="closeModal();openClient()">Nuovo cliente</button><button class="btn green" onclick="closeModal();openIntervention()">Nuovo intervento</button><button class="btn green" onclick="closeModal();openPlant()">Nuovo impianto</button><button class="btn green" onclick="closeModal();openAppointment()">Nuovo appuntamento</button><button class="btn" onclick="closeModal();openMaintenance()">Nuova manutenzione</button><button class="btn" onclick="closeModal();openQuote()">Nuovo preventivo</button><button class="btn" onclick="closeModal();openMaterial()">Nuovo articolo</button><button class="btn" onclick="closeModal();openExpense()">Nuova spesa</button></div>`)}
function home(){const open=db.interventions.filter(i=>!['chiuso','annullato','archiviato'].includes(i.status)).length, todayN=db.appointments.filter(a=>a.date===today()).length, low=db.materials.filter(m=>Number(m.stock)<=Number(m.minStock||0)).length;view.innerHTML=`<div class="hero"><div><div class="eyebrow">TECNOFA • CONTROL CENTER</div><h2>Un sistema, tutte le attività.</h2><p>Ogni cliente, impianto, intervento, materiale, documento e movimento resta collegato.</p></div><button class="btn green" onclick="quick()">＋ Nuova attività</button></div><div class="grid grid-4" style="margin-top:18px"><div class="card stat"><div class="label">Clienti</div><div class="value">${db.clients.length}</div><div class="sub">anagrafiche</div></div><div class="card stat"><div class="label">Impianti</div><div class="value">${db.plants.length}</div><div class="sub">schede tecniche</div></div><div class="card stat"><div class="label">Interventi aperti</div><div class="value">${open}</div><div class="sub">in gestione</div></div><div class="card stat"><div class="label">Appuntamenti oggi</div><div class="value">${todayN}</div><div class="sub">agenda operativa</div></div></div><div class="grid grid-2"><div>${header('Interventi recenti','<button class="btn" onclick="location.hash=\'#/interventi\'">Vedi tutti</button>')}<div class="card list">${db.interventions.slice().sort((a,b)=>(b.updatedAt||b.createdAt||'').localeCompare(a.updatedAt||a.createdAt||'')).slice(0,7).map(i=>`<div class="row"><div><b>${esc(i.title)}</b><div class="muted">${esc(cname(i.clientId))} · ${badge(i.status)}</div></div><button class="btn" onclick="editIntervention('${i.id}')">Apri</button></div>`).join('')||'<div class="empty">Nessun intervento.</div>'}</div></div><div>${header('Movimenti recenti','<button class="btn" onclick="globalHistory()">Storico completo</button>')}<div class="card list">${db.audit.slice().sort((a,b)=>b.at.localeCompare(a.at)).slice(0,8).map(x=>`<div class="row"><div><b>${esc(x.action)}</b><div class="muted">${esc(x.details)}</div></div><span class="muted">${new Date(x.at).toLocaleDateString('it-IT')}</span></div>`).join('')||'<div class="empty">Nessun movimento.</div>'}</div></div></div><div class="grid grid-3" style="margin-top:18px"><div class="card"><b>Scorte da controllare</b><div class="value">${low}</div><button class="btn" onclick="location.hash='#/magazzino'">Magazzino</button></div><div class="card"><b>Documenti</b><div class="value">${db.documents.length}</div><button class="btn" onclick="location.hash='#/documenti'">Archivio</button></div><div class="card"><b>Movimenti storici</b><div class="value">${db.audit.length}</div><button class="btn" onclick="globalHistory()">Apri storico</button></div></div>`}
function clienti(){view.innerHTML=header('Clienti','<button class="btn green" onclick="openClient()">＋ Nuovo cliente</button>')+`<div class="card"><table class="table"><thead><tr><th>Cliente</th><th>Contatti</th><th>Impianti</th><th>Interventi</th><th>Ultimo movimento</th><th></th></tr></thead><tbody>${db.clients.map(c=>{const ids=linkedIds(c.id),h=db.audit.filter(x=>ids.includes(x.entityId)).sort((a,b)=>b.at.localeCompare(a.at));return `<tr><td><b>${esc(c.name)}</b><br><span class="muted">${esc(c.address||c.city||'')}</span></td><td>${esc(c.phone||'')}<br>${esc(c.email||'')}</td><td>${db.plants.filter(x=>x.clientId===c.id).length}</td><td>${db.interventions.filter(x=>x.clientId===c.id).length}</td><td>${h[0]?new Date(h[0].at).toLocaleDateString('it-IT'):'—'}</td><td><button class="btn" onclick="editClient('${c.id}')">Apri scheda</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">Nessun cliente.</td></tr>'}</tbody></table></div>`}
function clientForm(c){return `<form id="client-form" class="form-grid">${field('Nome / Ragione sociale','name',c.name||'','text','required')}${field('Telefono','phone',c.phone)}${field('WhatsApp','whatsapp',c.whatsapp)}${field('Email','email',c.email,'email')}${field('Codice fiscale / P.IVA','taxId',c.taxId)}${field('PEC','pec',c.pec)}${field('Indirizzo','address',c.address)}${field('CAP','cap',c.cap)}${field('Comune','city',c.city)}${field('Provincia','province',c.province)}${field('Latitudine','lat',c.lat,'number','step="any"')}${field('Longitudine','lng',c.lng,'number','step="any"')}${select('Stato','status',['attivo','sospeso','archiviato'],c.status||'attivo')}${textarea('Note cliente','notes',c.notes)}<div class="field full"><button class="btn green">Salva anagrafica</button></div></form>`}
function openClient(id=null){const c=db.clients.find(x=>x.id===id)||{status:'attivo'};modal(`<h2>${id?'Scheda cliente':'Nuovo cliente'}</h2>${id?tabs([['Anagrafica',`clientTab('anag','${id}')`],['Impianti',`clientTab('impianti','${id}')`],['Interventi',`clientTab('interventi','${id}')`],['Manutenzioni',`clientTab('manutenzioni','${id}')`],['Preventivi',`clientTab('preventivi','${id}')`],['Documenti',`clientTab('documenti','${id}')`],['Storico movimenti',`clientTab('storico','${id}')`]]):''}<div id="client-body">${clientForm(c)}</div>`);bindClientForm(id)}
function bindClientForm(id){const f=$('#client-form');if(!f)return;f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));d.lat=Number(d.lat)||null;d.lng=Number(d.lng)||null;let c=db.clients.find(x=>x.id===id);if(c){Object.assign(c,d,{updatedAt:now()});log(c.id,'modifica cliente','Anagrafica aggiornata','client')}else{c={id:uid('cli'),createdAt:now(),...d};db.clients.push(c);log(c.id,'creazione cliente',c.name,'client')}save();closeModal();clienti();toast('Cliente salvato')}}
function clientTab(tab,id){const b=$('#client-body'),c=db.clients.find(x=>x.id===id);if(tab==='anag'){b.innerHTML=clientForm(c);bindClientForm(id);return}if(tab==='impianti'){b.innerHTML=header('Impianti collegati',`<button class="btn green" onclick="openPlant(null,'${id}')">＋ Impianto</button>`)+db.plants.filter(x=>x.clientId===id).map(p=>`<div class="card row"><div><b>${esc(p.name)}</b><div class="muted">${esc(p.type)} · ${esc(p.brand)} ${esc(p.model)} · ${esc(p.serial)}</div></div><button class="btn" onclick="editPlant('${p.id}')">Apri</button></div>`).join('')||'<div class="empty">Nessun impianto.</div>';return}if(tab==='interventi'){b.innerHTML=header('Interventi del cliente',`<button class="btn green" onclick="openIntervention(null,'${id}')">＋ Intervento</button>`)+db.interventions.filter(x=>x.clientId===id).map(i=>`<div class="card row"><div><b>${esc(i.title)}</b><div class="muted">${esc(i.date)} · ${badge(i.status)} · ${esc(pname(i.plantId))}</div></div><button class="btn" onclick="editIntervention('${i.id}')">Apri</button></div>`).join('')||'<div class="empty">Nessun intervento.</div>';return}if(tab==='manutenzioni'){b.innerHTML=header('Manutenzioni',`<button class="btn green" onclick="openMaintenance(null,'${id}')">＋ Manutenzione</button>`)+db.maintenance.filter(x=>x.clientId===id).map(m=>`<div class="card row"><div><b>${esc(m.title)}</b><div class="muted">${esc(m.nextDate||'—')} · ${esc(m.frequency||'')}</div></div><button class="btn" onclick="editMaintenance('${m.id}')">Apri</button></div>`).join('')||'<div class="empty">Nessuna manutenzione.</div>';return}if(tab==='preventivi'){b.innerHTML=header('Preventivi',`<button class="btn green" onclick="openQuote(null,'${id}')">＋ Preventivo</button>`)+db.quotes.filter(x=>x.clientId===id).map(q=>`<div class="card row"><div><b>${esc(q.number)}</b><div class="muted">${esc(q.title)} · € ${Number(q.total||0).toFixed(2)} · ${badge(q.status)}</div></div><button class="btn" onclick="editQuote('${q.id}')">Apri</button></div>`).join('')||'<div class="empty">Nessun preventivo.</div>';return}if(tab==='documenti'){b.innerHTML=header('Documenti',`<button class="btn green" onclick="openDocument(null,'${id}')">＋ Documento</button>`)+db.documents.filter(x=>x.clientId===id).map(d=>`<div class="card row"><div><b>${esc(d.name)}</b><div class="muted">${esc(d.type)} · ${esc(d.date||'')}</div></div><button class="btn" onclick="editDocument('${d.id}')">Apri</button></div>`).join('')||'<div class="empty">Nessun documento.</div>';return}b.innerHTML=`<div class="card"><h3>Storico completo cliente</h3><p class="muted">Include movimenti della scheda, impianti, interventi, manutenzioni, preventivi e documenti.</p>${historyHtml(linkedIds(id))}</div>`}
window.openClient=openClient;window.editClient=id=>openClient(id);window.clientTab=clientTab;
function impianti(){view.innerHTML=header('Impianti','<button class="btn green" onclick="openPlant()">＋ Nuovo impianto</button>')+`<div class="card"><table class="table"><thead><tr><th>Impianto</th><th>Cliente</th><th>Tipo</th><th>Marca / modello</th><th>Seriale</th><th>Scadenze</th><th></th></tr></thead><tbody>${db.plants.map(p=>`<tr><td><b>${esc(p.name)}</b></td><td>${esc(cname(p.clientId))}</td><td>${esc(p.type)}</td><td>${esc(p.brand)} ${esc(p.model)}</td><td>${esc(p.serial)}</td><td>${esc(p.warranty||'—')}</td><td><button class="btn" onclick="editPlant('${p.id}')">Apri scheda</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Nessun impianto.</td></tr>'}</tbody></table></div>`}
function plantForm(p){return `<form id="plant-form" class="form-grid">${field('Descrizione impianto','name',p.name||'','text','required')}<div class="field"><label>Cliente</label><select name="clientId" required>${options(db.clients,p.clientId,c=>c.name,'Seleziona cliente')}</select></div>${select('Categoria','type',['Caldaia','Climatizzazione','PDC','Fotovoltaico','Accumulo','Wallbox','Idraulico','Elettrico','Altro'],p.type||'Caldaia')}${field('Marca','brand',p.brand)}${field('Modello','model',p.model)}${field('Matricola / seriale','serial',p.serial)}${field('Anno installazione','installYear',p.installYear,'number')}${field('Potenza / taglia','power',p.power)}${field('Tecnologia / combustibile','technology',p.technology)}${field('Refrigerante','refrigerant',p.refrigerant)}${field('Garanzia fino a','warranty',p.warranty,'date')}${field('Contratto','contract',p.contract)}${textarea('Dati tecnici','technicalData',p.technicalData,'placeholder="Pressioni, temperature, tensioni, configurazioni, parametri..."')}${textarea('Configurazione / componenti','components',p.components,'placeholder="Generatore, unità, inverter, pompe, valvole, sensori..."')}${textarea('Note impianto','notes',p.notes)}<div class="field full"><button class="btn green">Salva scheda impianto</button></div></form>`}
function openPlant(id=null,clientId=null){const p=db.plants.find(x=>x.id===id)||{clientId:clientId||'',type:'Caldaia'};if(!db.clients.length&&!id){toast('Crea prima un cliente');return}modal(`<h2>${id?'Scheda impianto':'Nuovo impianto'}</h2>${id?tabs([['Scheda tecnica',`plantTab('scheda','${id}')`],['Interventi',`plantTab('interventi','${id}')`],['Manutenzioni',`plantTab('manutenzioni','${id}')`],['Documenti',`plantTab('documenti','${id}')`],['Storico',`plantTab('storico','${id}')`]]):''}<div id="plant-body">${plantForm(p)}</div>`);bindPlantForm(id)}
function bindPlantForm(id){const f=$('#plant-form');if(!f)return;f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));let p=db.plants.find(x=>x.id===id);if(p){Object.assign(p,d,{updatedAt:now()});log(p.id,'modifica impianto','Scheda tecnica aggiornata','plant')}else{p={id:uid('imp'),createdAt:now(),...d};db.plants.push(p);log(p.id,'creazione impianto',p.name,'plant')}save();closeModal();impianti();toast('Impianto salvato')}}
function plantTab(tab,id){const b=$('#plant-body');if(tab==='scheda'){b.innerHTML=plantForm(db.plants.find(x=>x.id===id));bindPlantForm(id);return}if(tab==='interventi')b.innerHTML=header('Interventi',`<button class="btn green" onclick="openIntervention(null,'${db.plants.find(x=>x.id===id)?.clientId||''}','${id}')">＋ Intervento</button>`)+db.interventions.filter(x=>x.plantId===id).map(i=>`<div class="card row"><div><b>${esc(i.title)}</b><div class="muted">${esc(i.date)} · ${badge(i.status)}</div></div><button class="btn" onclick="editIntervention('${i.id}')">Apri</button></div>`).join('')||'<div class="empty">Nessun intervento.</div>';if(tab==='manutenzioni')b.innerHTML=db.maintenance.filter(x=>x.plantId===id).map(m=>`<div class="card row"><div><b>${esc(m.title)}</b><div class="muted">Prossima: ${esc(m.nextDate||'—')}</div></div><button class="btn" onclick="editMaintenance('${m.id}')">Apri</button></div>`).join('')||'<div class="empty">Nessuna manutenzione.</div>';if(tab==='documenti')b.innerHTML=db.documents.filter(x=>x.plantId===id).map(d=>`<div class="card row"><div><b>${esc(d.name)}</b><div class="muted">${esc(d.type)}</div></div><button class="btn" onclick="editDocument('${d.id}')">Apri</button></div>`).join('')||'<div class="empty">Nessun documento.</div>';if(tab==='storico')b.innerHTML=historyHtml([id,...db.interventions.filter(x=>x.plantId===id).map(x=>x.id),...db.maintenance.filter(x=>x.plantId===id).map(x=>x.id)])}
window.openPlant=openPlant;window.editPlant=id=>openPlant(id);window.plantTab=plantTab;
function interventions(){view.innerHTML=header('Interventi','<button class="btn green" onclick="openIntervention()">＋ Nuovo intervento</button>')+`<div class="card"><table class="table"><thead><tr><th>Data</th><th>Richiesta</th><th>Cliente</th><th>Impianto</th><th>Stato</th><th>Ore</th><th>Totale</th><th></th></tr></thead><tbody>${db.interventions.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(i=>`<tr><td>${esc(i.date)}</td><td><b>${esc(i.title)}</b><br><span class="muted">${esc(i.type)}</span></td><td>${esc(cname(i.clientId))}</td><td>${esc(pname(i.plantId))}</td><td>${badge(i.status)}</td><td>${esc(i.hours||0)}</td><td>€ ${Number(i.total||0).toFixed(2)}</td><td><button class="btn" onclick="editIntervention('${i.id}')">Apri scheda</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">Nessun intervento.</td></tr>'}</tbody></table></div>`}
function interventionForm(i){const mats=i.materialLines||[];return `<form id="int-form" class="form-grid">${field('Data','date',i.date||today(),'date','required')}<div class="field"><label>Cliente</label><select name="clientId" required>${options(db.clients,i.clientId,c=>c.name,'Seleziona cliente')}</select></div><div class="field"><label>Impianto</label><select name="plantId">${options(db.plants.filter(p=>!i.clientId||p.clientId===i.clientId),i.plantId,p=>`${p.name} — ${cname(p.clientId)}`,'Nessun impianto')}</select></div>${select('Tipo','type',TYPES,i.type||'guasto')}${field('Titolo / richiesta cliente','title',i.title||'','text','required')}${select('Stato','status',STATES,i.status||'bozza')}${select('Priorità','priority',['normale','alta','urgente'],i.priority||'normale')}${field('Tecnico','technician',i.technician)}${field('Ora inizio','startTime',i.startTime,'time')}${field('Ora fine','endTime',i.endTime,'time')}${field('Ore lavoro','hours',i.hours||0,'number','step="0.25" min="0"')}${field('Km trasferta','km',i.km||0,'number','step="0.1" min="0"')}${field('Tempo viaggio','travelTime',i.travelTime)}${field('Numero rapportino','reportNo',i.reportNo)}${textarea('Richiesta / sintomo','request',i.request)}${textarea('Diagnosi / problema riscontrato','diagnosis',i.diagnosis)}${textarea('Lavoro eseguito','work',i.work)}${textarea('Misure e parametri','measurements',i.measurements,'placeholder="Pressioni, temperature, tensioni, correnti, errori, letture..."')}${textarea('Checklist','checklist',i.checklist,'placeholder="Controlli eseguiti, verifiche, sicurezza, collaudo..."')}${textarea('Materiali / ricambi','materialsUsed',i.materialsUsed,'placeholder="Dettaglio materiali. Per scaricare il magazzino usa la scheda Materiali."')}${select('Esito','outcome',['',...OUTCOMES],i.outcome||'')}${textarea('Note tecniche','notes',i.notes)}${textarea('Prossima azione / follow-up','nextAction',i.nextAction)}${field('Manodopera €','laborCost',i.laborCost||0,'number','step="0.01"')}${field('Materiali €','materialCost',i.materialCost||0,'number','step="0.01"')}${field('Trasferta €','travelCost',i.travelCost||0,'number','step="0.01"')}${field('Altri costi €','otherCost',i.otherCost||0,'number','step="0.01"')}${field('Totale €','total',i.total||0,'number','step="0.01"')}${textarea('Note amministrative','adminNotes',i.adminNotes)}<div class="field full"><div class="action-panel"><div><b>Operatività</b><p class="muted">Il timer registra il tempo di lavoro. I materiali scaricati generano movimenti di magazzino e restano nello storico.</p></div><div class="actions"><button type="button" class="btn" onclick="timerStart('${i.id||''}')">▶ Avvia timer</button><button type="button" class="btn" onclick="timerStop('${i.id||''}')">■ Ferma timer</button><button type="button" class="btn" onclick="printReport('${i.id||''}')">Stampa rapportino</button></div></div></div>${i.signature?`<div class="field full card"><b>Firma cliente acquisita</b><br><img src="${i.signature}" style="max-width:320px;background:#fff;border:1px solid #ddd;margin-top:8px"></div>`:''}<div class="field full"><button class="btn green">${i.id?'Salva modifiche':'Crea intervento'}</button></div></form>`}
function openIntervention(id=null,clientId=null,plantId=null){if(!db.clients.length&&!id){toast('Crea prima un cliente');return}const i=db.interventions.find(x=>x.id===id)||{status:'bozza',date:today(),clientId:clientId||'',plantId:plantId||'',priority:'normale',type:'guasto',hours:0,km:0,laborCost:0,materialCost:0,travelCost:0,otherCost:0,total:0};modal(`<h2>${id?'Scheda intervento':'Nuovo intervento'}</h2>${id?tabs([['Scheda completa',`intTab('scheda','${id}')`],['Materiali',`intTab('materiali','${id}')`],['Storico movimenti',`intTab('storico','${id}')`],['Cliente',`intTab('cliente','${id}')`],['Impianto',`intTab('impianto','${id}')`],['Documenti',`intTab('documenti','${id}')`],['Firma',`intTab('firma','${id}')`]]):''}<div id="int-body">${interventionForm(i)}</div>`);bindIntForm(i,id)}
function validateClose(i){const m=[];if(!i.clientId)m.push('cliente');if(!i.title)m.push('titolo/richiesta');if(!i.diagnosis&&!i.work)m.push('diagnosi o lavoro');if(!i.outcome)m.push('esito');if(!Number(i.hours))m.push('ore');return m}
function bindIntForm(i,id){const f=$('#int-form');f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f)),old=i.status;Object.assign(i,d);['hours','km','laborCost','materialCost','travelCost','otherCost','total'].forEach(k=>i[k]=Number(i[k])||0);i.updatedAt=now();if(i.status==='chiuso'){const m=validateClose(i);if(m.length){i.status=old;toast('Per chiudere mancano: '+m.join(', '));return}}if(!id){i.id=uid('int');i.createdAt=now();db.interventions.push(i);log(i.id,'creazione intervento',`${i.title} · ${cname(i.clientId)}`,'intervention')}else log(i.id,old!==i.status?'cambio stato':'modifica intervento',old!==i.status?`${old} → ${i.status}`:'Scheda aggiornata','intervention');save();openIntervention(i.id);toast('Intervento salvato')}}
function intTab(tab,id){const b=$('#int-body'),i=db.interventions.find(x=>x.id===id);if(tab==='scheda'){b.innerHTML=interventionForm(i);bindIntForm(i,id);return}if(tab==='storico'){b.innerHTML=`<div class="card"><h3>Storico intervento</h3>${historyHtml([id])}</div>`;return}if(tab==='cliente'){const c=db.clients.find(x=>x.id===i.clientId);b.innerHTML=`<div class="card"><h3>${esc(c?.name||'')}</h3><p>${esc(c?.address||'')}</p><p>${esc(c?.phone||'')} · ${esc(c?.email||'')}</p><button class="btn" onclick="editClient('${i.clientId}')">Apri scheda cliente</button></div>`;return}if(tab==='impianto'){const p=db.plants.find(x=>x.id===i.plantId);b.innerHTML=`<div class="card"><h3>${esc(p?.name||'Nessun impianto')}</h3><p>${esc(p?.brand||'')} ${esc(p?.model||'')}</p><p>${esc(p?.technicalData||'')}</p>${p?`<button class="btn" onclick="editPlant('${p.id}')">Apri scheda impianto</button>`:''}</div>`;return}if(tab==='materiali'){b.innerHTML=header('Materiali dell’intervento',`<button class="btn green" onclick="addStockUse('${id}')">＋ Scarica materiale</button>`)+`<div class="card"><table class="table"><thead><tr><th>Articolo</th><th>Quantità</th><th>Costo</th><th>Movimento</th></tr></thead><tbody>${db.stockMoves.filter(m=>m.interventionId===id).map(m=>`<tr><td>${esc(m.name)}</td><td>${m.qty}</td><td>€ ${(m.qty*m.cost).toFixed(2)}</td><td>${new Date(m.at).toLocaleString('it-IT')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Nessun materiale scaricato.</td></tr>'}</tbody></table></div>`;return}if(tab==='documenti'){b.innerHTML=header('Documenti collegati',`<button class="btn green" onclick="openDocument(null,'${i.clientId}','${i.plantId||''}','${id}')">＋ Documento</button>`)+db.documents.filter(d=>d.interventionId===id).map(d=>`<div class="card row"><div><b>${esc(d.name)}</b><div class="muted">${esc(d.type)} · ${esc(d.date||'')}</div></div><button class="btn" onclick="editDocument('${d.id}')">Apri</button></div>`).join('')||'<div class="empty">Nessun documento collegato.</div>';return}b.innerHTML=`<div class="card"><h3>Firma cliente</h3><p class="muted">La firma viene salvata nella scheda locale dell’intervento.</p><canvas id="sig" width="650" height="220" style="width:100%;border:1px solid #dce4df;border-radius:10px;background:#fff;touch-action:none"></canvas><div class="actions" style="margin-top:10px"><button class="btn" onclick="clearSig()">Cancella</button><button class="btn green" onclick="saveSig('${id}')">Salva firma</button></div></div>`;signatureCanvas()}
window.openIntervention=openIntervention;window.editIntervention=id=>openIntervention(id);window.intTab=intTab;
let timer={};function timerStart(id){if(!id){toast('Salva prima l’intervento');return}if(timer[id]){toast('Timer già attivo');return}timer[id]=Date.now();const i=db.interventions.find(x=>x.id===id);if(i&&!i.startTime)i.startTime=new Date().toTimeString().slice(0,5);log(id,'avvio timer','Timer intervento avviato','intervention');toast('Timer avviato')}function timerStop(id){if(!id||!timer[id]){toast('Nessun timer attivo');return}const sec=(Date.now()-timer[id])/1000;delete timer[id];const i=db.interventions.find(x=>x.id===id);if(i){i.hours=Math.round(((Number(i.hours)||0)+sec/3600)*100)/100;i.endTime=new Date().toTimeString().slice(0,5);i.updatedAt=now();log(id,'stop timer',`Tempo aggiunto: ${(sec/3600).toFixed(2)} h`,'intervention');save();openIntervention(id);toast('Tempo registrato')}}window.timerStart=timerStart;window.timerStop=timerStop;
function signatureCanvas(){const c=$('#sig');if(!c)return;const x=c.getContext('2d');let down=false;x.lineWidth=2;x.lineCap='round';const pos=e=>{const r=c.getBoundingClientRect(),p=e.touches?.[0]||e;return{x:(p.clientX-r.left)*c.width/r.width,y:(p.clientY-r.top)*c.height/r.height}};c.onpointerdown=e=>{down=true;const p=pos(e);x.beginPath();x.moveTo(p.x,p.y)};c.onpointermove=e=>{if(!down)return;const p=pos(e);x.lineTo(p.x,p.y);x.stroke()};c.onpointerup=()=>down=false;c.onpointerleave=()=>down=false}function clearSig(){const c=$('#sig');if(c)c.getContext('2d').clearRect(0,0,c.width,c.height)}function saveSig(id){const c=$('#sig'),i=db.interventions.find(x=>x.id===id);if(!c||!i)return;i.signature=c.toDataURL('image/png');i.signatureAt=now();log(id,'firma cliente','Firma acquisita','intervention');save();openIntervention(id);toast('Firma salvata')}window.clearSig=clearSig;window.saveSig=saveSig;
function addStockUse(interventionId){if(!db.materials.length){toast('Crea prima un articolo');return}modal(`<h2>Scarica materiale dall’intervento</h2><form id="stock-use" class="form-grid"><div class="field full"><label>Articolo</label><select name="materialId" required>${options(db.materials,'',m=>`${m.name} · giacenza ${m.stock}`,'Seleziona articolo')}</select></div>${field('Quantità','qty',1,'number','min="0.01" step="0.01" required')}${textarea('Nota','note')}<div class="field full"><button class="btn green">Registra scarico</button></div></form>`);$('#stock-use').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),m=db.materials.find(x=>x.id===d.materialId),qty=Number(d.qty)||0;if(!m||qty<=0)return;if(Number(m.stock)<qty){toast('Giacenza insufficiente');return}m.stock=Number(m.stock)-qty;const mv={id:uid('movstock'),materialId:m.id,name:m.name,qty,cost:Number(m.cost)||0,interventionId,kind:'scarico',at:now(),note:d.note};db.stockMoves.push(mv);const i=db.interventions.find(x=>x.id===interventionId);i.materialCost=(Number(i.materialCost)||0)+qty*(Number(m.cost)||0);log(interventionId,'scarico magazzino',`${m.name} × ${qty}`,'intervention');log(m.id,'movimento magazzino',`Scarico ${qty} per ${i.title}`,'material');save();closeModal();openIntervention(interventionId);toast('Materiale scaricato e collegato all’intervento')}}window.addStockUse=addStockUse;
function agenda(){view.innerHTML=header('Agenda','<button class="btn green" onclick="openAppointment()">＋ Appuntamento</button>')+`<div class="card list">${db.appointments.slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(a=>`<div class="row"><div><b>${esc(a.date)} ${esc(a.time)}</b> · ${esc(a.title)}<div class="muted">${esc(cname(a.clientId))} · ${esc(a.type)}</div></div><button class="btn" onclick="editAppointment('${a.id}')">Apri</button></div>`).join('')||'<div class="empty">Nessun appuntamento.</div>'}</div>`}
function openAppointment(id=null){const a=db.appointments.find(x=>x.id===id)||{date:today(),type:'intervento'};modal(`<h2>${id?'Modifica appuntamento':'Nuovo appuntamento'}</h2><form id="app-form" class="form-grid">${field('Data','date',a.date,'date','required')}${field('Ora','time',a.time,'time')}${field('Titolo','title',a.title,'text','required')}<div class="field"><label>Cliente</label><select name="clientId">${options(db.clients,a.clientId,c=>c.name,'Nessun cliente')}</select></div>${select('Tipo','type',['intervento','manutenzione','sopralluogo','consegna','telefonata','preventivo','personale'],a.type||'intervento')}${field('Tecnico','technician',a.technician)}${field('Intervento collegato','interventionId',a.interventionId)}${textarea('Note','notes',a.notes)}<div class="field full"><button class="btn green">Salva appuntamento</button></div></form>`);$('#app-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));let x=db.appointments.find(z=>z.id===id);if(x){Object.assign(x,d,{updatedAt:now()});log(id,'modifica appuntamento',x.title,'appointment')}else{x={id:uid('app'),createdAt:now(),...d};db.appointments.push(x);log(x.id,'creazione appuntamento',x.title,'appointment')}save();closeModal();agenda();toast('Appuntamento salvato')}}window.openAppointment=openAppointment;window.editAppointment=id=>openAppointment(id);
function maintenance(){view.innerHTML=header('Manutenzioni','<button class="btn green" onclick="openMaintenance()">＋ Nuova manutenzione</button>')+`<div class="card"><table class="table"><thead><tr><th>Prossima</th><th>Attività</th><th>Cliente</th><th>Impianto</th><th>Periodicità</th><th>Stato</th><th></th></tr></thead><tbody>${db.maintenance.map(m=>`<tr><td>${esc(m.nextDate||'—')}</td><td><b>${esc(m.title)}</b></td><td>${esc(cname(m.clientId))}</td><td>${esc(pname(m.plantId))}</td><td>${esc(m.frequency)}</td><td>${badge(m.status)}</td><td><button class="btn" onclick="editMaintenance('${m.id}')">Apri</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Nessuna manutenzione.</td></tr>'}</tbody></table></div>`}
function openMaintenance(id=null,clientId=null){const m=db.maintenance.find(x=>x.id===id)||{clientId:clientId||'',frequency:'annuale',status:'attiva'};modal(`<h2>${id?'Scheda manutenzione':'Nuova manutenzione'}</h2><form id="maint-form" class="form-grid">${field('Titolo','title',m.title,'text','required')}<div class="field"><label>Cliente</label><select name="clientId" required>${options(db.clients,m.clientId,c=>c.name,'Seleziona cliente')}</select></div><div class="field"><label>Impianto</label><select name="plantId">${options(db.plants,m.plantId,p=>`${p.name} — ${cname(p.clientId)}`,'Nessun impianto')}</select></div>${select('Periodicità','frequency',['mensile','trimestrale','semestrale','annuale','biennale','personalizzata'],m.frequency)}${field('Ultima esecuzione','lastDate',m.lastDate,'date')}${field('Prossima scadenza','nextDate',m.nextDate,'date')}${select('Stato','status',['attiva','sospesa','completata'],m.status||'attiva')}${textarea('Checklist','checklist',m.checklist)}${textarea('Note','notes',m.notes)}${field('Prezzo previsto €','price',m.price||0,'number','step="0.01"')}${field('Intervento generato','lastInterventionId',m.lastInterventionId)}<div class="field full"><button class="btn green">Salva manutenzione</button></div></form>`);$('#maint-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.price=Number(d.price)||0;let x=db.maintenance.find(z=>z.id===id);if(x){Object.assign(x,d,{updatedAt:now()});log(id,'modifica manutenzione',x.title,'maintenance')}else{x={id:uid('mnt'),createdAt:now(),...d};db.maintenance.push(x);log(x.id,'creazione manutenzione',x.title,'maintenance')}save();closeModal();maintenance();toast('Manutenzione salvata')}}window.openMaintenance=openMaintenance;window.editMaintenance=id=>openMaintenance(id);
function quotes(){view.innerHTML=header('Preventivi','<button class="btn green" onclick="openQuote()">＋ Nuovo preventivo</button>')+`<div class="card"><table class="table"><thead><tr><th>Numero</th><th>Cliente</th><th>Titolo</th><th>Totale</th><th>Stato</th><th></th></tr></thead><tbody>${db.quotes.map(q=>`<tr><td>${esc(q.number)}</td><td>${esc(cname(q.clientId))}</td><td>${esc(q.title)}</td><td>€ ${Number(q.total||0).toFixed(2)}</td><td>${badge(q.status)}</td><td><button class="btn" onclick="editQuote('${q.id}')">Apri</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nessun preventivo.</td></tr>'}</tbody></table></div>`}
function openQuote(id=null,clientId=null){const q=db.quotes.find(x=>x.id===id)||{status:'bozza',vat:0,discount:0,subtotal:0,clientId:clientId||''};modal(`<h2>${id?'Scheda preventivo':'Nuovo preventivo'}</h2><form id="quote-form" class="form-grid">${field('Numero','number',q.number||('PREV-'+new Date().getFullYear()+'-'+(db.quotes.length+1)))}<div class="field"><label>Cliente</label><select name="clientId" required>${options(db.clients,q.clientId,c=>c.name,'Seleziona cliente')}</select></div>${field('Titolo','title',q.title,'text','required')}${select('Stato','status',['bozza','inviato','visualizzato','accettato','rifiutato','scaduto'],q.status||'bozza')}${textarea('Descrizione','description',q.description)}${field('Imponibile €','subtotal',q.subtotal||0,'number','step="0.01"')}${field('Sconto €','discount',q.discount||0,'number','step="0.01"')}${field('IVA €','vat',q.vat||0,'number','step="0.01"')}${field('Totale €','total',q.total||0,'number','step="0.01" readonly')}${textarea('Note','notes',q.notes)}<div class="field full"><button class="btn green">Salva preventivo</button></div></form>`);$('#quote-form').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.subtotal=Number(d.subtotal)||0;d.discount=Number(d.discount)||0;d.vat=Number(d.vat)||0;d.total=d.subtotal-d.discount+d.vat;let x=db.quotes.find(z=>z.id===id);if(x){Object.assign(x,d,{updatedAt:now()});log(id,'modifica preventivo',x.number,'quote')}else{x={id:uid('prev'),createdAt:now(),...d};db.quotes.push(x);log(x.id,'creazione preventivo',x.number,'quote')}save();closeModal();quotes();toast('Preventivo salvato')}}window.openQuote=openQuote;window.editQuote=id=>openQuote(id);
function warehouse(){const low=db.materials.filter(m=>Number(m.stock)<=Number(m.minStock||0)).length;view.innerHTML=header('Magazzino',`<button class="btn green" onclick="openMaterial()">＋ Articolo</button>`)+`<div class="grid grid-3"><div class="card"><b>Articoli</b><div class="value">${db.materials.length}</div></div><div class="card"><b>Scorte da riordinare</b><div class="value">${low}</div></div><div class="card"><b>Movimenti</b><div class="value">${db.stockMoves.length}</div></div></div><div class="card" style="margin-top:18px"><table class="table"><thead><tr><th>Codice</th><th>Articolo</th><th>Categoria</th><th>Giacenza</th><th>Minimo</th><th>Costo</th><th></th></tr></thead><tbody>${db.materials.map(m=>`<tr><td>${esc(m.code)}</td><td><b>${esc(m.name)}</b></td><td>${esc(m.category)}</td><td>${m.stock<=m.minStock?'<b>':''}${m.stock}${m.stock<=m.minStock?'</b>':''}</td><td>${m.minStock}</td><td>€ ${Number(m.cost||0).toFixed(2)}</td><td><button class="btn" onclick="editMaterial('${m.id}')">Apri</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Nessun articolo.</td></tr>'}</tbody></table></div>`}
function openMaterial(id=null){const m=db.materials.find(x=>x.id===id)||{stock:0,minStock:0,cost:0,price:0};modal(`<h2>${id?'Scheda articolo':'Nuovo articolo'}</h2>${id?tabs([['Scheda',`materialTab('scheda','${id}')`],['Movimenti',`materialTab('movimenti','${id}')`]]):''}<div id="mat-body"><form id="mat-form" class="form-grid">${field('Codice','code',m.code)}${field('Nome articolo','name',m.name,'text','required')}${field('Categoria','category',m.category)}${field('Marca','brand',m.brand)}${field('Unità','unit',m.unit||'pz')}${field('Giacenza','stock',m.stock||0,'number')}${field('Scorta minima','minStock',m.minStock||0,'number')}${field('Costo unitario €','cost',m.cost||0,'number','step="0.01"')}${field('Prezzo €','price',m.price||0,'number','step="0.01"')}${textarea('Note','notes',m.notes)}<div class="field full"><button class="btn green">Salva articolo</button></div></form></div>`);bindMaterial(id)}
function bindMaterial(id){const f=$('#mat-form');if(!f)return;f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));['stock','minStock','cost','price'].forEach(k=>d[k]=Number(d[k])||0);let x=db.materials.find(z=>z.id===id);if(x){Object.assign(x,d,{updatedAt:now()});log(id,'modifica articolo',x.name,'material')}else{x={id:uid('mat'),createdAt:now(),...d};db.materials.push(x);log(x.id,'creazione articolo',x.name,'material')}save();closeModal();warehouse();toast('Articolo salvato')}}function materialTab(t,id){const b=$('#mat-body');if(t==='scheda'){const m=db.materials.find(x=>x.id===id);b.innerHTML=`<form id="mat-form" class="form-grid">${field('Codice','code',m.code)}${field('Nome articolo','name',m.name,'text','required')}${field('Categoria','category',m.category)}${field('Marca','brand',m.brand)}${field('Unità','unit',m.unit||'pz')}${field('Giacenza','stock',m.stock||0,'number')}${field('Scorta minima','minStock',m.minStock||0,'number')}${field('Costo unitario €','cost',m.cost||0,'number','step="0.01"')}${field('Prezzo €','price',m.price||0,'number','step="0.01"')}${textarea('Note','notes',m.notes)}<div class="field full"><button class="btn green">Salva articolo</button></div></form>`;bindMaterial(id)}else b.innerHTML=`<div class="card"><h3>Movimenti articolo</h3>${db.stockMoves.filter(x=>x.materialId===id).sort((a,b)=>b.at.localeCompare(a.at)).map(x=>`<div class="row"><div><b>${esc(x.kind)} · ${x.qty}</b><div class="muted">${esc(x.note||'Intervento collegato')}</div></div><span class="muted">${new Date(x.at).toLocaleString('it-IT')}</span></div>`).join('')||'<div class="empty">Nessun movimento.</div>'}</div>`}window.openMaterial=openMaterial;window.editMaterial=id=>openMaterial(id);window.materialTab=materialTab;
function economy(){const income=db.interventions.reduce((s,i)=>s+Number(i.total||0),0)+db.quotes.filter(q=>q.status==='accettato').reduce((s,q)=>s+Number(q.total||0),0),expenses=db.expenses.reduce((s,e)=>s+Number(e.amount||0),0),costs=db.interventions.reduce((s,i)=>s+Number(i.laborCost||0)+Number(i.materialCost||0)+Number(i.travelCost||0)+Number(i.otherCost||0),0);view.innerHTML=`${header('Economia','<button class="btn green" onclick="openExpense()">＋ Spesa</button>')}<div class="grid grid-4"><div class="card stat"><div class="label">Ricavi</div><div class="value">€ ${income.toFixed(0)}</div></div><div class="card stat"><div class="label">Spese</div><div class="value">€ ${expenses.toFixed(0)}</div></div><div class="card stat"><div class="label">Costi interventi</div><div class="value">€ ${costs.toFixed(0)}</div></div><div class="card stat"><div class="label">Margine indicativo</div><div class="value">€ ${(income-expenses-costs).toFixed(0)}</div></div></div>${header('Spese registrate')}<div class="card"><table class="table"><thead><tr><th>Data</th><th>Categoria</th><th>Descrizione</th><th>Importo</th><th></th></tr></thead><tbody>${db.expenses.map(e=>`<tr><td>${esc(e.date)}</td><td>${esc(e.category)}</td><td>${esc(e.description)}</td><td>€ ${Number(e.amount||0).toFixed(2)}</td><td><button class="btn" onclick="editExpense('${e.id}')">Apri</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nessuna spesa.</td></tr>'}</tbody></table></div>`}
function openExpense(id=null){const e=db.expenses.find(x=>x.id===id)||{date:today()};modal(`<h2>${id?'Modifica spesa':'Nuova spesa'}</h2><form id="exp-form" class="form-grid">${field('Data','date',e.date,'date','required')}${field('Categoria','category',e.category)}${field('Descrizione','description',e.description,'text','required')}${field('Importo €','amount',e.amount||0,'number','step="0.01"')}${textarea('Note','notes',e.notes)}<div class="field full"><button class="btn green">Salva spesa</button></div></form>`);$('#exp-form').onsubmit=x=>{x.preventDefault();const d=Object.fromEntries(new FormData(x));d.amount=Number(d.amount)||0;let z=db.expenses.find(a=>a.id===id);if(z){Object.assign(z,d);log(id,'modifica spesa',z.description,'expense')}else{z={id:uid('exp'),createdAt:now(),...d};db.expenses.push(z);log(z.id,'creazione spesa',z.description,'expense')}save();closeModal();economy();toast('Spesa salvata')}}window.openExpense=openExpense;window.editExpense=id=>openExpense(id);
function documents(){view.innerHTML=header('Documenti','<button class="btn green" onclick="openDocument()">＋ Documento</button>')+`<div class="card"><table class="table"><thead><tr><th>Data</th><th>Documento</th><th>Tipo</th><th>Cliente</th><th>Intervento</th><th></th></tr></thead><tbody>${db.documents.map(d=>`<tr><td>${esc(d.date)}</td><td><b>${esc(d.name)}</b></td><td>${esc(d.type)}</td><td>${esc(cname(d.clientId))}</td><td>${esc(db.interventions.find(i=>i.id===d.interventionId)?.title||'—')}</td><td><button class="btn" onclick="editDocument('${d.id}')">Apri</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nessun documento.</td></tr>'}</tbody></table></div>`}
function openDocument(id=null,clientId=null,plantId=null,interventionId=null){const d=db.documents.find(x=>x.id===id)||{date:today(),type:'rapportino',clientId:clientId||'',plantId:plantId||'',interventionId:interventionId||''};modal(`<h2>${id?'Scheda documento':'Nuovo documento'}</h2><form id="doc-form" class="form-grid">${field('Data','date',d.date,'date')}${select('Tipo','type',['rapportino','preventivo','contratto','manuale','fattura','foto','verbale','altro'],d.type||'rapportino')}${field('Nome documento','name',d.name,'text','required')}<div class="field"><label>Cliente</label><select name="clientId">${options(db.clients,d.clientId,c=>c.name,'Nessun cliente')}</select></div><div class="field"><label>Impianto</label><select name="plantId">${options(db.plants,d.plantId,p=>`${p.name} — ${cname(p.clientId)}`,'Nessun impianto')}</select></div><div class="field"><label>Intervento</label><select name="interventionId">${options(db.interventions,d.interventionId,i=>`${i.date} · ${i.title}`,'Nessun intervento')}</select></div>${field('Riferimento file / URL','fileRef',d.fileRef)}${textarea('Descrizione','description',d.description)}<div class="field full"><button class="btn green">Salva documento</button></div></form>`);$('#doc-form').onsubmit=e=>{e.preventDefault();const x=Object.fromEntries(new FormData(e.target));let z=db.documents.find(a=>a.id===id);if(z){Object.assign(z,x,{updatedAt:now()});log(id,'modifica documento',z.name,'document')}else{z={id:uid('doc'),createdAt:now(),...x};db.documents.push(z);log(z.id,'creazione documento',z.name,'document')}save();closeModal();documents();toast('Documento salvato')}}window.openDocument=openDocument;window.editDocument=id=>openDocument(id);
function mapPage(){view.innerHTML=`<div class="hero"><div><div class="eyebrow">OPERATIVO</div><h2>Mappa & percorsi</h2><p>Clienti geolocalizzati e interventi aperti.</p></div></div><div class="grid grid-2" style="margin-top:18px"><div class="card"><h3>Clienti geolocalizzati</h3>${db.clients.filter(c=>c.lat&&c.lng).map(c=>`<div class="row"><div><b>${esc(c.name)}</b><div class="muted">${c.lat}, ${c.lng}</div></div><button class="btn" onclick="window.open('https://www.google.com/maps/search/?api=1&query=${c.lat},${c.lng}','_blank')">Naviga</button></div>`).join('')||'<div class="empty">Inserisci coordinate nella scheda cliente.</div>'}</div><div class="card"><h3>Interventi da gestire</h3>${db.interventions.filter(i=>!['chiuso','annullato'].includes(i.status)).slice(0,12).map(i=>`<div class="row"><div><b>${esc(i.title)}</b><div class="muted">${esc(i.date)} · ${esc(cname(i.clientId))}</div></div><button class="btn" onclick="editIntervention('${i.id}')">Apri</button></div>`).join('')||'<div class="empty">Nessun intervento.</div>'}</div></div>`}
function energy(){view.innerHTML=`<div class="hero"><div><div class="eyebrow">TECNOFA ENERGY</div><h2>Energia e domotica</h2><p>Area predisposta per fotovoltaico, batterie, consumi, EV, clima, ACS e Home Assistant.</p></div></div><div class="grid grid-3" style="margin-top:18px"><div class="card"><h3>Fotovoltaico</h3><p class="muted">Produzione, inverter, zero export.</p></div><div class="card"><h3>Accumulo</h3><p class="muted">SOC, carica e scarica.</p></div><div class="card"><h3>Home Assistant</h3><p class="muted">Integrazione tecnica successiva.</p></div></div>`}
function aiPage(){view.innerHTML=`<div class="hero"><div><div class="eyebrow">TECNOFA AI</div><h2>Dalla voce al rapportino.</h2><p>Struttura pronta per trasformare appunti tecnici in una scheda.</p></div></div><div class="card" style="margin-top:18px"><textarea id="ai-text" placeholder="Scrivi gli appunti dell’intervento..."></textarea><br><button class="btn green" onclick="aiPrepare()">Prepara struttura</button><div id="ai-result" style="margin-top:14px"></div></div>`}function aiPrepare(){const t=$('#ai-text').value;$('#ai-result').innerHTML=`<div class="card"><b>Bozza</b><p>${esc(t)}</p><p class="muted">Pronta per essere trasformata in richiesta, diagnosi, lavoro, materiali ed esito.</p></div>`}
function printReport(id){const i=db.interventions.find(x=>x.id===id);if(!i){toast('Salva prima l’intervento');return}const c=db.clients.find(x=>x.id===i.clientId),p=db.plants.find(x=>x.id===i.plantId);const mats=db.stockMoves.filter(x=>x.interventionId===id);const w=window.open('','_blank');w.document.write(`<html><head><title>Rapportino TECNOFA</title><style>body{font-family:Arial;padding:35px;color:#1a232c}h1{color:#63ad3d}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}.box{border:1px solid #ddd;border-radius:10px;padding:14px;margin:12px 0}</style></head><body><h1>TECNOFA</h1><h2>Rapportino intervento</h2><div class="box"><b>${esc(i.title)}</b><br>${esc(i.date)} · ${esc(i.status)}<br>Cliente: ${esc(c?.name||'')}<br>Impianto: ${esc(p?.name||'')}</div><div class="box"><b>Richiesta</b><p>${esc(i.request)}</p><b>Diagnosi</b><p>${esc(i.diagnosis)}</p><b>Lavoro eseguito</b><p>${esc(i.work)}</p><b>Misure</b><p>${esc(i.measurements)}</p><b>Esito</b><p>${esc(i.outcome)}</p></div><div class="box"><b>Materiali</b><table><tr><th>Articolo</th><th>Q.tà</th><th>Costo</th></tr>${mats.map(m=>`<tr><td>${esc(m.name)}</td><td>${m.qty}</td><td>€ ${(m.qty*m.cost).toFixed(2)}</td></tr>`).join('')}</table></div><div class="box"><b>Consuntivo</b><p>Ore: ${i.hours} · Km: ${i.km}</p><p>Manodopera € ${Number(i.laborCost||0).toFixed(2)} · Materiali € ${Number(i.materialCost||0).toFixed(2)} · Trasferta € ${Number(i.travelCost||0).toFixed(2)}</p><h3>Totale € ${Number(i.total||0).toFixed(2)}</h3></div>${i.signature?`<div class="box"><b>Firma cliente</b><br><img src="${i.signature}" width="320"></div>`:''}<script>window.print()<\/script></body></html>`);w.document.close()}
window.printReport=printReport;
function settings(){view.innerHTML=header('Impostazioni')+`<div class="grid grid-2"><div class="card"><h3>Storico globale</h3><p class="muted">Tutte le operazioni importanti mantengono data, entità e dettaglio.</p><button class="btn" onclick="globalHistory()">Apri storico movimenti</button></div><div class="card"><h3>Dati locali</h3><p>${db.clients.length} clienti · ${db.plants.length} impianti · ${db.interventions.length} interventi · ${db.audit.length} movimenti</p><button class="btn" onclick="backup()">Esporta backup JSON</button></div><div class="card"><h3>Catena dati</h3><p class="muted">Cliente → Impianto → Intervento → Materiali → Documenti → Economia → Manutenzione → Storico.</p></div><div class="card"><h3>Versione dati</h3><p class="muted">TECNOFA V5 · struttura locale collegata.</p></div></div>`}
function globalHistory(){modal(`<h2>Storico movimenti globale</h2>${historyHtml(db.audit.map(x=>x.entityId))}`)}function backup(){const b=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='tecnofa-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}window.globalHistory=globalHistory;window.backup=backup;
save();nav();